def _zip_dir_impl(ctx):
    out = ctx.actions.declare_file(ctx.label.name + ".zip")
    ctx.actions.run_shell(
        inputs = ctx.files.srcs,
        outputs = [out],
        tools = [ctx.executable._zipper],
        command = "{zipper} c {out} {files}".format(
            zipper = ctx.executable._zipper.path,
            out = out.path,
            files = " ".join([f.path for f in ctx.files.srcs]),
        ),
    )
    return [DefaultInfo(files = depset([out]))]

zip_dir = rule(
    implementation = _zip_dir_impl,
    attrs = {
        "srcs": attr.label_list(allow_files = True),
        "_zipper": attr.label(default = "@bazel_tools//tools/zip:zipper", executable = True, cfg = "exec"),
    },
)

