load("//tools/build_defs:hash.bzl", "hashed_file")

def _stem(src):
    return src.rsplit("/", 1)[-1].replace(".", "_")

def hashed_assets(name, srcs):
    for src in srcs:
        hashed_file(
            name = "%s_%s" % (name, _stem(src)),
            src = src,
        )
    native.filegroup(
        name = name,
        srcs = [":%s_%s" % (name, _stem(s)) for s in srcs],
    )
